28:MODE=full; DO_RESUME=0; DO_TOOLS=1; FULL_TESTS=0; CONTINUE=0; NO_AUTOSAVE=0   # DO_RESUME=1 only with --resume
38:  --skip-resume) DO_RESUME=0 ;;
39:  --resume|--merge) DO_RESUME=1 ;;  # explicit, on the user's request only
114:merge_one() {  # ref -> 0 merged | 1 conflict (aborted) | 2 refused
116:  if git merge --no-edit -q -m "resume: merge newer saved work from ${ref#origin/}" "$ref" >/dev/null 2>&1; then return 0; fi
118:    git -c commit.gpgsign=false merge --no-edit -q -m "resume: merge newer saved work from ${ref#origin/}" "$ref" >/dev/null 2>&1 && return 0
126:      git merge-file --union "$tmpd/o" "$tmpd/b" "$tmpd/t"; cp "$tmpd/o" "$f"; git add -- "$f"
132:    git merge --abort; return 1
135:  git merge --abort 2>/dev/null; return 2
139:  local t merged="" conflicts="" refused="" total=0 contained=0 dirty ref; t=$(now)
144:    rec resume "Newer saved work (no auto-merge)" fail "git fetch from GitHub failed (network / GitHub connection?)" "$t"; return

